:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #292b32;
  background: #f5efe4;
  --ink: #292b32;
  --muted: #73747b;
  --accent: #6558a5;
  --line: #e6e0d6;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 36px 18px;
  display: grid;
  place-items: center;
  background-color: #f5efe4;
  background-image: radial-gradient(#dfd7ca 1px, transparent 1px);
  background-size: 22px 22px;
}
button, textarea { font: inherit; }
button { cursor: pointer; }
.board-card {
  width: min(760px, 100%);
  padding: clamp(22px, 5vw, 42px);
  border: 1px solid #e8e1d6;
  border-radius: 24px;
  background: #fffdf9;
  box-shadow: 0 18px 50px #5a4d3817, 0 3px 8px #5a4d380d;
}
.board-header, .section-heading, .form-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.eyebrow { margin: 0 0 6px; color: var(--accent); font-size: .86rem; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(2rem, 6vw, 2.8rem); letter-spacing: -.05em; line-height: 1.1; }
.count { flex: none; margin: 0; padding: 9px 14px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); font-size: .95rem; }
.count #note-count { color: var(--ink); font-weight: 750; }
.note-form { margin-top: 30px; padding: 20px; border: 1px solid var(--line); border-radius: 16px; background: #faf8f3; }
.note-form > label, .color-picker legend { display: block; margin-bottom: 9px; font-size: .94rem; font-weight: 700; }
textarea { display: block; width: 100%; min-height: 88px; padding: 12px 14px; resize: vertical; border: 1px solid #dcd6cc; border-radius: 10px; outline: none; background: #fff; color: var(--ink); line-height: 1.5; }
textarea::placeholder { color: #99969a; }
textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 3px #6558a526; }
.form-row { margin-top: 16px; align-items: end; }
.color-picker { display: flex; align-items: center; gap: 10px; margin: 0; padding: 0; border: 0; }
.color-picker legend { float: left; margin: 0 7px 0 0; padding: 0; }
.swatch { position: relative; display: inline-flex; width: 30px; height: 30px; cursor: pointer; }
.swatch input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.swatch span { width: 30px; height: 30px; border: 2px solid #ffffff; border-radius: 50%; box-shadow: 0 0 0 1px #d9d3c9; }
.swatch-yellow span { background: #f6df86; }
.swatch-pink span { background: #f0b9bd; }
.swatch-blue span { background: #acd4e6; }
.swatch-green span { background: #b9d8ae; }
.swatch input:checked + span { box-shadow: 0 0 0 2px var(--accent); }
.swatch input:focus-visible + span { outline: 3px solid #6558a555; outline-offset: 3px; }
.add-button, .clear-button, .note-action {
  min-height: 42px; padding: 9px 15px; border: 0; border-radius: 10px; font-weight: 700;
  transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease;
}
.add-button { background: var(--accent); color: white; }
.add-button:hover { background: #554891; }
.add-button:active, .clear-button:active, .note-action:active { transform: translateY(1px); }
button:focus-visible { outline: 3px solid #6558a566; outline-offset: 3px; }
.notes-section { margin-top: 32px; }
.section-heading { padding-bottom: 13px; border-bottom: 1px solid var(--line); }
h2 { margin: 0; font-size: 1.15rem; }
.clear-button { min-height: 36px; padding: 7px 11px; border: 1px solid #e5d6d5; background: #fff; color: #9b5558; font-size: .9rem; }
.clear-button:hover:not(:disabled) { background: #fff0ef; }
.clear-button:disabled { cursor: not-allowed; opacity: .45; }
.empty-state { margin: 24px 0; color: var(--muted); text-align: center; }
.notes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 205px), 1fr)); gap: 16px; margin: 18px 0 0; padding: 0; list-style: none; }
.note { min-height: 168px; padding: 16px; border-radius: 4px 4px 12px 4px; box-shadow: 0 5px 12px #4a40351a; transform: rotate(-.7deg); }
.note:nth-child(even) { transform: rotate(.8deg); }
.note-yellow { background: #fff0b8; }
.note-pink { background: #f8d6d7; }
.note-blue { background: #d2eaf3; }
.note-green { background: #d8e9ce; }
.note-text { min-height: 82px; margin: 0 0 14px; overflow-wrap: anywhere; white-space: pre-wrap; line-height: 1.5; }
.note textarea { min-height: 82px; margin-bottom: 14px; border-color: #00000018; background: #ffffff80; }
.note-actions { display: flex; gap: 8px; }
.note-action { min-height: 34px; padding: 6px 10px; border: 1px solid #26262620; background: #ffffff75; font-size: .88rem; }
.note-action:hover { background: #ffffffc9; }
.note-action.delete { color: #8b4043; }
footer { margin-top: 28px; color: #8c8984; font-size: .85rem; text-align: center; }
footer span { color: var(--accent); }
@media (max-width: 520px) {
  body { padding: 16px 10px; }
  .board-card { padding: 22px 18px; border-radius: 18px; }
  .form-row { align-items: stretch; flex-direction: column; }
  .color-picker { justify-content: flex-start; flex-wrap: wrap; }
  .color-picker legend { width: 100%; margin-bottom: 2px; }
  .add-button { width: 100%; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const form = document.querySelector('#note-form');
const input = document.querySelector('#note-text');
const list = document.querySelector('#notes-list');
const count = document.querySelector('#note-count');
const countLabel = document.querySelector('#count-label');
const emptyState = document.querySelector('#empty-state');
const clearButton = document.querySelector('#clear-all');

function updateBoard() {
  const total = list.children.length;
  count.textContent = total;
  countLabel.textContent = total === 1 ? 'note' : 'notes';
  emptyState.hidden = total > 0;
  clearButton.disabled = total === 0;
}

function makeAction(label, className, callback) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `note-action ${className}`;
  button.textContent = label;
  button.addEventListener('click', callback);
  return button;
}

function addNote(text, color) {
  const item = document.createElement('li');
  item.className = `note note-${color}`;
  const content = document.createElement('p');
  content.className = 'note-text';
  content.textContent = text;
  const actions = document.createElement('div');
  actions.className = 'note-actions';

  const editButton = makeAction('Edit', 'edit', () => {
    const editor = document.createElement('textarea');
    editor.setAttribute('aria-label', 'Edit note text');
    editor.maxLength = 280;
    editor.value = content.textContent;
    content.replaceWith(editor);
    editButton.textContent = 'Save';
    editButton.setAttribute('aria-label', 'Save note');
    editor.focus();

    const save = () => {
      const updated = editor.value.trim();
      if (!updated) { editor.focus(); return; }
      content.textContent = updated;
      editor.replaceWith(content);
      editButton.textContent = 'Edit';
      editButton.setAttribute('aria-label', 'Edit note');
    };
    editButton.addEventListener('click', save, { once: true });
    editor.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) save();
      if (event.key === 'Escape') {
        editor.replaceWith(content);
        editButton.textContent = 'Edit';
        editButton.setAttribute('aria-label', 'Edit note');
      }
    });
  });
  editButton.setAttribute('aria-label', 'Edit note');
  const deleteButton = makeAction('Delete', 'delete', () => {
    item.remove();
    updateBoard();
  });
  deleteButton.setAttribute('aria-label', 'Delete note');

  actions.append(editButton, deleteButton);
  item.append(content, actions);
  list.prepend(item);
  updateBoard();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) { input.focus(); return; }
  const color = form.querySelector('input[name="note-color"]:checked').value;
  addNote(text, color);
  input.value = '';
  input.focus();
});

clearButton.addEventListener('click', () => {
  if (!list.children.length) return;
  if (window.confirm('Clear all notes from your board?')) {
    list.replaceChildren();
    updateBoard();
  }
});

updateBoard();
